import{c as a,Q as l,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E5%AF%B9%E5%8E%9F%E5%A7%8B%E7%A8%80%E7%96%8F%E7%9F%A9%E9%98%B5B%E8%BF%9B%E8%A1%8C4-2%E7%A8%A0%E5%AF%86%E5%8C%96%E8%BF%87%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.Dj7tvTnL.png",m=JSON.parse('{"title":"4:2稀疏矩阵乘","description":"","frontmatter":{},"headers":[{"level":1,"title":"4:2稀疏矩阵乘","slug":"42稀疏矩阵乘"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"实现流程","slug":"实现流程"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/4-2稀疏矩阵乘.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/4-2稀疏矩阵乘.md"}'),o={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/4-2稀疏矩阵乘.md"};function p(i,t,r,u,g,c){return l(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="_4-2稀疏矩阵乘" tabindex="-1">4:2稀疏矩阵乘 <a class="header-anchor" href="#_4-2稀疏矩阵乘" aria-label="Permalink to &quot;4:2稀疏矩阵乘&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>4:2稀疏矩阵乘，又称Sparse Matmul。该场景下输入的原始左矩阵A、右矩阵B为稀疏矩阵，稀疏矩阵B中每4个元素中至少有2个为零元素；在进行Matmul计算前，用户需要自行对B矩阵进行4：2稠密化，即基于原始稀疏矩阵B在每4个元素中过滤掉2个零元素，使B矩阵稠密化为稠密矩阵；Sparse Matmul场景调用Matmul API完成A矩阵与4:2稠密化后的B矩阵的矩阵乘计算。Sparse Matmul可以跳过稀疏矩阵B中的零元素，仅对非零元素进行数据搬运存储和计算，从而减少矩阵乘计算时的内存占用和计算量，提升性能。</p><h2 id="实现流程" tabindex="-1">实现流程 <a class="header-anchor" href="#实现流程" aria-label="Permalink to &quot;实现流程&quot;">​</a></h2><ol><li><p>数据预处理</p><p>在计算前的数据准备阶段，用户自行对原始为稀疏矩阵的B矩阵完成稠密化，稠密过程请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MmadWithSparse.md" target="_blank" rel="noreferrer">稠密算法说明</a>。稠密化过程结束后，得到4:2稠密化后的右矩阵B和索引矩阵index，稠密化后的右矩阵B和索引矩阵index将作为Sparse Matmul场景的计算输入。</p><p><strong>图 1</strong> 对原始稀疏矩阵B进行4:2稠密化过程示意图<br><img src="'+n+`" alt="" title="对原始稀疏矩阵B进行4-2稠密化过程示意图"></p><p>稠密化过程对于稀疏矩阵B的每4个元素，在索引矩阵index中生成2个2位索引，每个索引分别指向对应非零元素的相对位置，具体规则可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MmadWithSparse.md" target="_blank" rel="noreferrer">稠密算法说明</a>。稠密化过程生成的索引矩阵的数据类型为int2，索引矩阵在加载入Matmul前，需要拼成int8的数据类型。索引矩阵在一个int8的地址中的排布是逆序排布的，例如：索引矩阵1 2 0 1 0 2 1 0，在地址中的排布为1 0 2 1 0 1 2 0，其中1 0 2 1（对应索引矩阵前四位1 2 0 1）为一个int8，0 1 2 0（对应索引矩阵后四位0 2 1 0）为一个int8。</p></li><li><p>使能Sparse Matmul场景</p><p>在Host侧，<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTiling.md" target="_blank" rel="noreferrer">获取Tiling</a>前需要通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSparse.md" target="_blank" rel="noreferrer">SetSparse</a>接口设置使能Sparse Matmul场景。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT8); </span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT8);  </span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT32);</span></span>
<span class="line"><span>tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT32);  </span></span>
<span class="line"><span>// 设置使能Sparse Matmul场景</span></span>
<span class="line"><span>tiling.SetSparse(true);</span></span>
<span class="line"><span>... // 其他实现内容</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int ret = tiling.GetTiling(tilingData);</span></span></code></pre></div></li><li><p>创建Matmul对象</p><p>在Kernel侧创建Matmul对象时，通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul%E4%BD%BF%E7%94%A8%E8%AF%B4%E6%98%8E.md" target="_blank" rel="noreferrer">MatmulType</a>定义A、C、Bias的参数类型信息，包括：内存逻辑位置、数据格式、数据类型。通过<a href="#zh-cn_topic_0000002298767897_table3658657131020">SparseMatmulType</a>类型定义B矩阵的参数类型，包括：B矩阵的内存逻辑位置、索引矩阵的内存逻辑位置、数据格式、数据类型等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, ATYPE, false&gt;;</span></span>
<span class="line"><span>// 使用SparseMatmulType定义B矩阵的参数类型信息</span></span>
<span class="line"><span>using B_TYPE = AscendC::SparseMatmulType&lt;AscendC::TPosition::GM, AscendC::TPosition::GM, CubeFormat::ND, BType, true&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MDL&gt; mm;</span></span></code></pre></div></li><li><p>设置索引矩阵</p><p>通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSparseIndex.md" target="_blank" rel="noreferrer">SetSparseIndex</a>接口传入稠密化过程中生成的索引矩阵。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.SetTensorA(gm_a);    // 设置左矩阵A</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);    // 设置右矩阵B</span></span>
<span class="line"><span>mm.SetSparseIndex(gm_index); // 传入稠密化过程中生成的索引矩阵</span></span>
<span class="line"><span>mm.SetBias(gm_bias);    // 设置Bias</span></span></code></pre></div></li><li><p>完成矩阵乘操作</p><p>在Kernel侧，基于<a href="#zh-cn_topic_0000002298767897_li52321325141410">步骤4</a>加载的索引矩阵，完成矩阵乘操作。Matmul API内部完成对A矩阵的稠密化，即根据索引矩阵从A矩阵的每4个元素中，选择2个对应位置元素参与计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 调用Iterate和GetTensorC或IterateAll接口完成矩阵乘计算</span></span>
<span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(gm_c); </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// mm.IterateAll(gm_c);</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div></li></ol><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> SparseMatmulType类型参数说明</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;参数&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;POSITION&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;内存逻辑位置。&lt;/p&gt; &lt;p&gt;B矩阵仅支持设置为TPosition::GM。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;INDEX_POSITION&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;索引矩阵内存逻辑位置。&lt;/p&gt; &lt;p&gt;仅支持设置为TPosition::GM。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;CubeFormat&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;数据的物理排布格式，详细介绍请参考&lt;a href=&quot;../基础知识.md#zh-cn_topic_0000001622194138_section1453415011&quot;&gt;数据格式。&lt;/p&gt; &lt;p&gt;B矩阵支持设置为CubeFormat::ND，CubeFormat::NZ。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;TYPE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;B矩阵仅支持设置为int8_t数据类型。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;ISTRANS&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;是否开启使能矩阵转置的功能。&lt;/p&gt; &lt;p&gt;当前只支持取值为true，表示开启使能矩阵转置的功能。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;LAYOUT&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;表征数据的排布。Sparse Matmul场景仅支持取值为LAYOUT::NONE。&lt;/p&gt; &lt;p&gt;NONE：默认值，表示不使用BatchMatmul。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.21%&quot;&gt;&lt;p&gt;IBSHARE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;78.79%&quot;&gt;&lt;p&gt;是否使能IBShare（IntraBlock Share）。IBShare的功能是能够复用L1 Buffer上相同的A矩阵或B矩阵数据。当A矩阵和B矩阵同时使能IBShare时，表示L1 Buffer上的A矩阵和B矩阵同时复用。&lt;/p&gt; &lt;p&gt;Sparse Matmul场景当前仅支持该参数取值为false，表示不使能IBShare。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>左矩阵A为稀疏矩阵、右矩阵B为4:2稠密化后的矩阵的Matmul计算场景。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>该场景仅支持<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MDL模板</a>下的纯Cube模式（只有矩阵计算）。</li><li>通过SetSparseIndex接口传入的索引矩阵只支持int8数据类型和<a href="./../../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.html#li19960204116136">NZ数据排布格式</a>。</li><li>原始稀疏矩阵B中每4个元素中应保证最多2个非零元素（即最少2个零元素），如果存在3个或更多非零元素，则仅使用前2个非零元素。</li><li>M、K、N中的任意一个值不能为0。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>Sparse Matmul场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_sparse" target="_blank" rel="noreferrer">Sparse Matmul场景的算子样例</a>。</p>`,14)])])}const h=a(o,[["render",p]]);export{m as __pageData,h as default};
